package githubrunner

import("context";"fmt";"sort";"strings";"github.com/example-user/runnerhub/internal/core")
type PoolSecurityPosture struct{Safe bool `json:"safe"`;RunnerGroup *RunnerGroup `json:"runnerGroup,omitempty"`;Repository *Repository `json:"repository,omitempty"`;AccessibleRepositories []string `json:"accessibleRepositories,omitempty"`;Reasons []string `json:"reasons,omitempty"`;Warnings []string `json:"warnings,omitempty"`}
func InspectPoolSecurity(ctx context.Context,c Catalog,p core.RunnerPool)(PoolSecurityPosture,error){out:=PoolSecurityPosture{};if c==nil{return out,fmt.Errorf("github catalog is not configured")};if p.Scope.Kind==core.ScopeRepository{repo,err:=c.GetRepository(ctx,p.Scope.Owner,p.Scope.Repository);if err!=nil{return out,err};out.Repository=&repo;if !repo.Private{out.Reasons=append(out.Reasons,"repository is public; RunnerHub trusted self-hosted runners require a private repository")};out.Safe=len(out.Reasons)==0;return out,nil};group,err:=c.GetRunnerGroup(ctx,p.Scope.Owner,p.RunnerGroupID);if err!=nil{return out,err};out.RunnerGroup=&group;repos:=[]Repository{};if strings.EqualFold(group.Visibility,"selected"){repos,err=c.ListRunnerGroupRepositories(ctx,p.Scope.Owner,p.RunnerGroupID);if err!=nil{return out,err};for _,r:=range repos{out.AccessibleRepositories=append(out.AccessibleRepositories,r.FullName);if !r.Private{out.Reasons=append(out.Reasons,"runner group grants access to public repository "+r.FullName)}}};if group.AllowsPublicRepositories{out.Reasons=append(out.Reasons,"runner group allows public repositories")};if len(p.AllowedRepositories)>0{if !strings.EqualFold(group.Visibility,"selected"){out.Reasons=append(out.Reasons,"pool has a repository allowlist but GitHub runner group visibility is broader than selected repositories")}else{allowed:=lowerSet(p.AllowedRepositories);actual:=map[string]bool{};for _,r:=range repos{actual[strings.ToLower(r.FullName)]=true;if !allowed[strings.ToLower(r.FullName)]{out.Reasons=append(out.Reasons,"GitHub runner group additionally allows repository "+r.FullName)}};for _,want:=range p.AllowedRepositories{if !actual[strings.ToLower(want)]{out.Warnings=append(out.Warnings,"pool allows "+want+" but GitHub runner group does not")}}}};if len(p.AllowedWorkflows)>0{if !group.RestrictedToWorkflows{out.Reasons=append(out.Reasons,"pool has a workflow allowlist but GitHub runner group is not restricted to selected workflows")}else{allowed:=lowerSet(p.AllowedWorkflows);actual:=map[string]bool{};for _,wf:=range group.SelectedWorkflows{actual[strings.ToLower(wf)]=true;if !allowed[strings.ToLower(wf)]{out.Reasons=append(out.Reasons,"GitHub runner group additionally allows workflow "+wf)}};for _,want:=range p.AllowedWorkflows{if !actual[strings.ToLower(want)]{out.Warnings=append(out.Warnings,"pool allows "+want+" but GitHub runner group does not")}}}};sort.Strings(out.AccessibleRepositories);sort.Strings(out.Reasons);sort.Strings(out.Warnings);out.Safe=len(out.Reasons)==0;return out,nil}
func lowerSet(in []string)map[string]bool{out:=map[string]bool{};for _,v:=range in{out[strings.ToLower(strings.TrimSpace(v))]=true};return out}
